-- ── Post-condition assertions ───────────────────────────────────────────
DO $$
DECLARE
  v_total      integer;
  v_verified   integer;
  v_unverified integer;
  v_max_order  integer;
BEGIN
  SELECT count(*) INTO v_total FROM public.ladieci_schema_migrations WHERE kind = 'bootstrap';
  SELECT count(*) INTO v_verified FROM public.ladieci_schema_migrations WHERE kind = 'bootstrap' AND verification_status = 'verified';
  SELECT count(*) INTO v_unverified FROM public.ladieci_schema_migrations WHERE kind = 'bootstrap' AND verification_status = 'bootstrapped_unverified';
  SELECT max(apply_order) INTO v_max_order FROM public.ladieci_schema_migrations;

  IF v_total <> 73 THEN
    RAISE EXCEPTION 'S4 bootstrap-seed post-condition failed: expected 73 bootstrap rows, found %', v_total;
  END IF;
  IF v_verified <> 38 THEN
    RAISE EXCEPTION 'S4 bootstrap-seed post-condition failed: expected 38 verified rows, found %', v_verified;
  END IF;
  IF v_unverified <> 35 THEN
    RAISE EXCEPTION 'S4 bootstrap-seed post-condition failed: expected 35 bootstrapped_unverified rows, found %', v_unverified;
  END IF;
  IF v_max_order <> 73 THEN
    RAISE EXCEPTION 'S4 bootstrap-seed post-condition failed: expected max(apply_order) = 73, found %', v_max_order;
  END IF;
END $$;
